import{_ as t,o as e,c as o,ag as r}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"SetPayload 设置负载参数","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetPayload.md","filePath":"3. 指令/5. 设置指令/SetPayload.md","lastUpdated":1778862643000}'),s={name:"3. 指令/5. 设置指令/SetPayload.md"};function d(n,a,l,i,h,p){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="setpayload-设置负载参数" tabindex="-1">SetPayload 设置负载参数 <a class="header-anchor" href="#setpayload-设置负载参数" aria-label="Permalink to &quot;SetPayload 设置负载参数&quot;">​</a></h1><p>该指令用于<strong>设置机器人末端当前承载的工件负载参数</strong>。准确设置负载质量及重心位置对于机器人的运动精度、路径平滑度以及减速机的使用寿命至关重要。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetPayload(pl) SetPayload(负载质量参数)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>pl：负载质量（Payload）</td><td>PAYLOAD 变量</td><td>包含工件物理属性的结构化变量。通常包括：<br>* <strong>质量 (Mass)</strong>：工件的重量（单位：kg）。<br>* <strong>重心 (Center of Gravity)</strong>：工件重心相对于工具法兰中心或 TCP 的偏移位置（X, Y, Z）。<br>* <strong>惯量 (Inertia)</strong>：工件绕各个轴的转动惯量。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>机器人的控制算法需要根据负载大小实时计算关节所需的扭矩（动力学补偿）。执行 <code>SetPayload</code> 后，系统会立即更新动力学模型。如果设置的负载远轻于实际重量，机器人停止时可能会产生震荡或过冲；如果设置过重，则会限制机器人的加速性能。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetPayload</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(PAYLOAD1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>执行结果：</strong></p><p>系统启用变量 <strong>PAYLOAD1</strong> 中定义的物理参数，后续所有运动（<code>MovJ</code>, <code>MovL</code> 等）将基于该负载进行动力学计算。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>抓取与释放</strong>：机器人在空载运行（仅有夹具）和负载运行（夹具 + 工件）之间切换时，必须调用该指令切换对应的负载参数。</li><li><strong>码垛作业</strong>：根据码垛物料的不同规格（如不同重量的包装箱），动态切换负载参数以优化运行稳定性。</li><li><strong>寿命保护</strong>：通过准确设置负载，防止电机长时间超负荷运行，降低减速机磨损。</li></ul>',18)])])}const b=t(s,[["render",d]]);export{u as __pageData,b as default};
